def solve(x):
    chunks = []
    remainder = []
    for i in range(0, len(x['items']) - x['size'], x['size']):
        chunks.append(x['items'][i:i + x['size']])
    if x['items'][-x['size']:]:
        chunks.append(x['items'][-x['size']:])
    return {'chunks': chunks, 'remainder': remainder}
